/**
 * Detail models (`?detail=1`): one place that answers a DetailRequest, used by POST /api/detail and by
 * npm run predetail, so a pre-made topic is made by exactly the same code as a live one.
 *
 * Order: memory -> disk (.cache-live/detail/<key>.json) -> a pre-made topic that matches the request well
 * (docs/detail-topics.json, already generated by npm run predetail) -> Claude (detailLive). The key is the
 * request's object and topic in plain words (detailKey in shared/detail.ts), so a repeat is instant. Two
 * requests for the same key at once share one Claude call. Everything is AI-made, kept, not reviewed.
 */
import fs from 'node:fs';
import path from 'node:path';
import { bestPremade, detailKey, type DetailRequest, type DetailScene, type PremadeTopic } from '../../shared/detail';
import { ROOT, readLiveDetail, writeLiveDetail } from './cache';
import { detailLive, DETAIL_TIMEOUT_MS } from './claude';
import { hasAnthropic } from './env';

/** Sentences the voice tutor can say (one each). */
export const DETAIL_SAY = {
  failed: 'I could not build a model of that just now. Try again in a moment.',
  slow: 'That model took too long to build. Try again in a moment.',
  noKey: 'I cannot build new detail models without a Claude key.',
} as const;

export type DetailFailure = keyof typeof DETAIL_SAY;

export class DetailError extends Error {
  constructor(
    public kind: DetailFailure,
    detail: string,
  ) {
    super(detail);
    this.name = 'DetailError';
  }
  get say(): string {
    return DETAIL_SAY[this.kind];
  }
}

export const PREMADE_FILE = path.join(ROOT, 'docs', 'detail-topics.json');

/** docs/detail-topics.json: [{ topic, object? }]; [] if it is missing or unreadable. */
export function readPremades(): PremadeTopic[] {
  try {
    const raw = JSON.parse(fs.readFileSync(PREMADE_FILE, 'utf8')) as unknown;
    const list = Array.isArray(raw) ? raw : raw && typeof raw === 'object' && Array.isArray((raw as { topics?: unknown }).topics) ? (raw as { topics: unknown[] }).topics : [];
    return list
      .map((v) => (v && typeof v === 'object' ? (v as Record<string, unknown>) : {}))
      .filter((v) => typeof v.topic === 'string' && v.topic.trim())
      .map((v) => ({ topic: String(v.topic).trim(), ...(typeof v.object === 'string' && v.object.trim() ? { object: v.object.trim() } : {}) }));
  } catch {
    return [];
  }
}

const memory = new Map<string, DetailScene>();
const inFlight = new Map<string, Promise<DetailScene>>();

export interface DetailHit {
  scene: DetailScene;
  key: string;
  /** where it came from; "claude" = generated just now */
  from: 'memory' | 'disk' | 'premade' | 'claude';
  seconds: number;
}

/** A kept scene for a key: memory, then disk (which then fills memory). */
function kept(key: string): DetailScene | null {
  const m = memory.get(key);
  if (m) return m;
  const d = readLiveDetail(key);
  if (d) memory.set(key, d);
  return d;
}

/**
 * The scene for a request. `force` (npm run predetail -- --force) skips the caches and makes it again.
 * Throws DetailError: noKey (no Anthropic key and nothing kept), slow (time limit), failed (anything else).
 */
export async function getDetail(req: DetailRequest, opts: { force?: boolean; timeoutMs?: number } = {}): Promise<DetailHit> {
  const started = Date.now();
  const secs = () => Math.round((Date.now() - started) / 100) / 10;
  const key = detailKey(req.topic, req.object);
  if (!opts.force) {
    const m = memory.get(key);
    if (m) return { scene: m, key, from: 'memory', seconds: secs() };
    const d = kept(key);
    if (d) return { scene: d, key, from: 'disk', seconds: secs() };
    // A pre-made topic worded a little differently ("the battery" for "battery cell ... during discharge").
    const p = bestPremade(req, readPremades());
    if (p) {
      const pk = detailKey(p.topic, p.object);
      const ps = kept(pk);
      if (ps) {
        memory.set(key, ps);
        return { scene: ps, key: pk, from: 'premade', seconds: secs() };
      }
    }
  }
  if (!hasAnthropic()) throw new DetailError('noKey', 'no ANTHROPIC_API_KEY (or MOCK=1)');
  let run = inFlight.get(key);
  if (!run) {
    run = detailLive(req, opts.timeoutMs ?? DETAIL_TIMEOUT_MS).finally(() => inFlight.delete(key));
    inFlight.set(key, run);
  }
  try {
    const scene = await run;
    memory.set(key, scene);
    writeLiveDetail(key, scene);
    return { scene, key, from: 'claude', seconds: secs() };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    const timedOut = /time(d)?\s?out|timeout/i.test(message) || (err instanceof Error && /Timeout/i.test(err.name));
    throw new DetailError(timedOut ? 'slow' : 'failed', message);
  }
}
